"""Compare immutable JMH jars using identical fast N-Quads benchmark bytecode and settings."""

import argparse
import csv
import datetime
import hashlib
import json
import math
import os
from pathlib import Path
import platform
import re
import shlex
import shutil
import signal
import subprocess
import sys
from zipfile import ZipFile


BASE_COMMIT = "2a843fff41f53a118ce92295be76a4af515a58a0"
PACKAGE = "org.eclipse.rdf4j.sail.lmdb.bulk."
BENCHMARKS = ("FastNQuadsParserBenchmark", "FastNQuadsStagingBenchmark")
REPO = Path(__file__).resolve().parent.parent


def arguments():
    parser = argparse.ArgumentParser(description=__doc__, epilog=(
        "No checkout or build is performed. See docs/fast-nquads-benchmarks.md for isolated builds. "
        "Git labels are recorded as supplied, never treated as verified jar provenance."))
    parser.add_argument("--baseline-module", type=Path, required=True)
    parser.add_argument("--candidate-module", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True, help="New directory; existing evidence is never replaced")
    parser.add_argument("--benchmark", choices=("block", "stream", "stage", "all"), default="all")
    parser.add_argument("--baseline-label", default=BASE_COMMIT)
    parser.add_argument("--candidate-label", default="candidate")
    parser.add_argument("--warmup-iterations", type=int, help="Defaults to 3 for parsing, 2 for staging")
    parser.add_argument("--measurement-iterations", type=int, default=4)
    parser.add_argument("--forks", type=int, default=2)
    parser.add_argument("--iteration-time", help="Override both warmup and measurement duration")
    parser.add_argument("--heap", help="Fixed heap for both runtimes; defaults to 512m for parsing, 1g for staging")
    parser.add_argument("--jvm-arg", action="append", default=[], help="Additional JVM argument; repeatable")
    parser.add_argument("--parser-terms", help="Comma-separated override; all declared benchmark values by default")
    parser.add_argument("--workers", help="Override staging worker counts; JMH always uses one thread")
    parser.add_argument("--terms", help="Override staging term distributions")
    parser.add_argument("--characters", help="Override staging character distributions")
    parser.add_argument("--compression", help="Override staging compression parameter")
    parser.add_argument("--verify-only", action="store_true", help="Snapshot and verify jars; do not launch JMH")
    parser.add_argument("--dry-run", action="store_true", help="Snapshot, verify and print commands without launching JMH")
    args = parser.parse_args()
    if (args.warmup_iterations is not None and args.warmup_iterations < 0) or args.measurement_iterations < 1 or args.forks < 1:
        parser.error("warmups must be nonnegative; measurements and forks must be positive")
    if args.iteration_time is not None and not re.fullmatch(r"[1-9][0-9]*(ns|us|ms|s|m|h)", args.iteration_time):
        parser.error("--iteration-time must be a positive JMH duration such as 1s")
    if args.heap is not None and not re.fullmatch(r"[1-9][0-9]*[kKmMgG]?", args.heap):
        parser.error("--heap must be a positive JVM memory size such as 1g")
    return args


def sha256(path):
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def benchmark_entry(name):
    return name.endswith(".class") and any(
        name.startswith((PACKAGE + benchmark).replace(".", "/"))
        or name.startswith((PACKAGE + "jmh_generated/" + benchmark).replace(".", "/"))
        for benchmark in BENCHMARKS)


def snapshot(module, destination):
    target = module.resolve() / "target"
    candidates = sorted(path for pattern in ("*.jar", "*/*.jar") for path in target.glob(pattern)
                        if ("jmh" in path.name or "benchmark" in path.name)
                        and not path.name.startswith("original-"))
    if len(candidates) != 1:
        raise ValueError(f"Expected exactly one benchmark jar in {target}, found {candidates}")
    destination.parent.mkdir(parents=True)
    shutil.copyfile(candidates[0], destination)
    with ZipFile(destination) as jar:
        names = jar.namelist()
        if len(names) != len(set(names)):
            raise ValueError(f"Duplicate archive entries make the runtime ambiguous: {destination}")
        harness = {name: hashlib.sha256(jar.read(name)).hexdigest() for name in names if benchmark_entry(name)}
        for benchmark in BENCHMARKS:
            required = (PACKAGE + benchmark).replace(".", "/") + ".class"
            if required not in harness:
                raise ValueError(f"Missing {required} in {destination}")
        metadata = {}
        for resource in ("META-INF/BenchmarkList", "META-INF/CompilerHints"):
            metadata[resource] = sorted(line for line in jar.read(resource).decode("utf-8").splitlines()
                                        if any(benchmark in line for benchmark in BENCHMARKS))
        if not metadata["META-INF/BenchmarkList"]:
            raise ValueError(f"No parser/staging JMH entries in {destination}")
        prefix = PACKAGE.replace(".", "/")
        production = {name: hashlib.sha256(jar.read(name)).hexdigest() for name in names
                      if name.startswith(prefix) and name.endswith(".class")
                      and "Benchmark" not in name and "/jmh_generated/" not in name}
    return {"input_jar": str(candidates[0]), "snapshot_jar": str(destination), "jar_sha256": sha256(destination),
            "benchmark_class_sha256": harness, "benchmark_metadata": metadata, "production_class_sha256": production}


def read_optional(path):
    try:
        return Path(path).read_text().strip()
    except OSError:
        return None


def environment():
    java = shutil.which("java")
    version = subprocess.run([java, "-version"], capture_output=True, text=True, check=True) if java else None
    cpuinfo = read_optional("/proc/cpuinfo") or ""
    cpu_model = next((line.split(":", 1)[1].strip() for line in cpuinfo.splitlines()
                      if line.startswith("model name")), platform.processor())
    return {"timestamp_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "platform": platform.platform(), "cpu_model": cpu_model, "logical_cpus": os.cpu_count(),
            "cpu_quota": read_optional("/sys/fs/cgroup/cpu.max"),
            "memory_limit": read_optional("/sys/fs/cgroup/memory.max"),
            "java_executable": java, "java_version": (version.stdout + version.stderr).strip() if version else None,
            "java_environment": {key: os.environ.get(key) for key in ("JAVA_HOME", "JAVA_TOOL_OPTIONS",
                                                                     "JDK_JAVA_OPTIONS", "_JAVA_OPTIONS")}}


def jobs(args, output):
    selected = []
    for name, method in (("block", "parseBlock"), ("stream", "parseStream")):
        if args.benchmark in (name, "all"):
            selected.append((name, BENCHMARKS[0], method,
                             [f"terms={args.parser_terms}"] if args.parser_terms else []))
    if args.benchmark in ("stage", "all"):
        parameters = [f"{key}={getattr(args, key)}" for key in ("workers", "terms", "characters", "compression")
                      if getattr(args, key) is not None]
        selected.append(("stage", BENCHMARKS[1], "stage", parameters))
    result = []
    for name, benchmark, method, parameters in selected:
        warmups = args.warmup_iterations if args.warmup_iterations is not None else (2 if name == "stage" else 3)
        warmup_time = args.iteration_time or "1s"
        measurement_time = args.iteration_time or ("2s" if name == "stage" else "1s")
        heap = args.heap or ("1g" if name == "stage" else "512m")
        jvm_args = [f"-Xms{heap}", f"-Xmx{heap}", *args.jvm_arg]
        for side in ("baseline", "candidate"):
            directory = output / side
            command = ["bash", str(REPO / "scripts/run-single-benchmark.sh"), "--no-build",
                       "--module", os.path.relpath(directory, REPO), "--class", PACKAGE + benchmark,
                       "--method", method, "--warmup-iterations", str(warmups),
                       "--measurement-iterations", str(args.measurement_iterations), "--forks", str(args.forks)]
            for parameter in parameters:
                command.extend(["--param", parameter])
            for argument in jvm_args:
                command.extend(["--jvm-arg", argument])
            command.extend(["--", "-w", warmup_time, "-r", measurement_time, "-t", "1",
                            "-prof", "gc", "-foe", "true", "-rf", "json", "-rff", str(directory / f"{name}.json")])
            result.append({"side": side, "name": name, "command": command})
    return result


def run_job(job, output):
    directory = output / job["side"]
    console_log = directory / f"{job['name']}.console.log"
    raw_log = directory / f"{job['name']}.jmh.log"
    runner_log = directory / "target/benchmark-output.log"
    if runner_log.exists():
        runner_log.rename(directory / f"{job['name']}.previous-runner.log")
    print(f"Measuring {job['side']} {job['name']}; logs: {console_log}", flush=True)
    try:
        with console_log.open("w") as log:
            log.write(shlex.join(job["command"]) + "\n")
            log.flush()
            with subprocess.Popen(job["command"], cwd=REPO, stdout=log, stderr=subprocess.STDOUT,
                                  start_new_session=True) as process:
                try:
                    status = process.wait()
                except BaseException:
                    os.killpg(process.pid, signal.SIGTERM)
                    try:
                        process.wait(timeout=5)
                    except subprocess.TimeoutExpired:
                        os.killpg(process.pid, signal.SIGKILL)
                        process.wait()
                    raise
            if status:
                raise RuntimeError(f"JMH exited with status {status}; see {console_log}")
    finally:
        if runner_log.exists():
            shutil.copyfile(runner_log, raw_log)


def summarize(output, planned):
    rows = []
    for name in dict.fromkeys(job["name"] for job in planned):
        results = {}
        for side in ("baseline", "candidate"):
            items = json.loads((output / side / f"{name}.json").read_text())
            results[side] = {(item["benchmark"], tuple(sorted(item.get("params", {}).items()))): item for item in items}
            if not items or len(items) != len(results[side]):
                raise ValueError(f"Empty or duplicate JMH results for {side} {name}")
        if results["baseline"].keys() != results["candidate"].keys():
            raise ValueError(f"Baseline and candidate JMH parameter sets differ for {name}")
        for key, before in results["baseline"].items():
            after = results["candidate"][key]
            for setting in ("mode", "threads", "forks", "jvmArgs", "jmhVersion", "jdkVersion", "warmupIterations",
                            "warmupTime", "measurementIterations", "measurementTime"):
                if before.get(setting) != after.get(setting):
                    raise ValueError(f"Mismatched {setting} for {key}")
            base, candidate = before["primaryMetric"], after["primaryMetric"]
            if base["scoreUnit"] != candidate["scoreUnit"] or base["score"] <= 0:
                raise ValueError(f"Incomparable JMH primary metrics for {key}")
            ratio = candidate["score"] / base["score"]
            rows.append({"benchmark": key[0], "params": json.dumps(dict(key[1]), sort_keys=True),
                         "unit": base["scoreUnit"], "baseline": base["score"], "candidate": candidate["score"],
                         "ratio": ratio if math.isfinite(ratio) else None,
                         "baseline_error": base["scoreError"], "candidate_error": candidate["scoreError"],
                         "baseline_bytes_per_op": before.get("secondaryMetrics", {}).get("gc.alloc.rate.norm", {}).get("score"),
                         "candidate_bytes_per_op": after.get("secondaryMetrics", {}).get("gc.alloc.rate.norm", {}).get("score")})
    with (output / "comparison.csv").open("w", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)
    (output / "comparison.json").write_text(json.dumps(rows, indent=2) + "\n")


def main():
    args = arguments()
    output = args.output_dir.resolve()
    output.mkdir(parents=True, exist_ok=False)
    manifest = {"status": "preparing", "producer_labels_verified": False,
                "producer_labels": {"baseline": args.baseline_label, "candidate": args.candidate_label},
                "producer_provenance": "Labels are caller assertions; jar/source origin requires independent verification.",
                "allocation_note": "Staging GC metrics may include invocation fixture allocations; parser trial setup is excluded.",
                "settings": {key: str(value) if isinstance(value, Path) else value for key, value in vars(args).items()}}
    try:
        manifest["environment"] = environment()
        manifest["runner_sha256"] = sha256(REPO / "scripts/run-single-benchmark.sh")
        jars = {side: snapshot(module, output / side / "target/jmh.jar") for side, module in
                (("baseline", args.baseline_module), ("candidate", args.candidate_module))}
        manifest["jars"] = jars
        for key in ("benchmark_class_sha256", "benchmark_metadata"):
            if jars["baseline"][key] != jars["candidate"][key]:
                raise ValueError(f"Benchmark harness differs ({key}); rebuild both jars with identical benchmark sources")
        if jars["baseline"]["production_class_sha256"] == jars["candidate"]["production_class_sha256"]:
            print("Warning: production bytecode is identical; this comparison measures run-to-run noise.", file=sys.stderr)
        planned = jobs(args, output)
        manifest["jobs"] = planned
        manifest["status"] = "verified"
        if args.dry_run:
            for job in planned:
                print(shlex.join(job["command"]))
        if not args.verify_only and not args.dry_run:
            version = manifest["environment"]["java_version"] or ""
            major = re.search(r'version "([0-9]+)', version)
            if not major or int(major.group(1)) < 25:
                raise ValueError("Set JAVA_HOME/PATH to JDK 25 or newer before running these benchmarks")
            manifest["status"] = "running"
            (output / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
            for job in planned:
                run_job(job, output)
            summarize(output, planned)
            manifest["status"] = "completed"
    except BaseException as error:
        manifest["status"] = "failed"
        manifest["failure"] = str(error)
        raise
    finally:
        (output / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Evidence preserved in {output}")


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, RuntimeError, subprocess.CalledProcessError) as error:
        raise SystemExit(str(error))
